// Zweck: Antwort von Cloudflare Whisper pruefen und als Feld transkript weitergeben.
// Leerer Text (Stille, unverstaendliche Aufnahme) nimmt den Fehlerweg "Bitte tippen", damit kein leerer Auftrag an K1 geht.
const text = String($input.first().json.result?.text ?? '').trim();
if (!text) {
  throw new Error('Cloudflare Whisper lieferte keinen Text');
}
return [{ json: { transkript: text } }];

// Zweck: Telegram-Nachricht ohne Sprachmodell einordnen (Kunde, Quellenart, Thema), Regeln laut Planung 10.10.2026.
const cfg = $('Einstellungen setzen [Edit Fields]').first().json;
// Text: aus dem Sprachzweig, wenn er gelaufen ist, sonst aus der Nachricht selbst.
const ausSprache = $('Text übernehmen [Edit Fields]').isExecuted;
const roh = ausSprache ? $('Text übernehmen [Edit Fields]').first().json.text : cfg.text;
let text = String(roh || '').replace(/\s+/g, ' ').trim();
const hinweise = ['Auftrag über Telegram (' + (ausSprache ? 'Sprachnachricht' : 'Text') + ')'];
// Kundenliste aus Supabase; kommt ein Fehler-Item, gilt nur der Standardkunde (Fallback mit Spur).
const zeilen = $input.all().map(i => i.json);
const listeFehlt = zeilen.some(z => z.error);
if (listeFehlt) hinweise.push('Kundenliste nicht lesbar, Standardkunde genommen');
const kuerzel = zeilen.filter(z => z.kuerzel).map(z => String(z.kuerzel).toLowerCase());
const standard = String(cfg.standard_kunde || '').toLowerCase();
const max = Number(cfg.max_text) || 12000;
// Ausgabe mit denselben Feldern wie das K1-Formular, dazu Steuerfelder fuer die Weiche.
// Warum englisch (12.10.2026, Ae7): K1 Bk8PXBGm3gXMATK1 erwartet seit v09 customer_code, topic, source_type, source, note; der Eingang sendet sie jetzt direkt.
const aus = { valid: false, error_reason: '', customer_code: '', customer_recognized: false, topic: '', source_type: '', source: '', note: '', chat_id: cfg.chat_id, channel: ausSprache ? 'sprache' : 'text', k1_workflow_id: String(cfg.k1_workflow_id || '') };
function fertig(grund) {
  aus.error_reason = grund;
  aus.valid = !grund;
  aus.note = hinweise.join('; ');
  // Telegram sendet mit parse_mode HTML, deshalb das Thema fuer die Anzeige maskieren.
  aus.topic_display = aus.topic.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  return [{ json: aus }];
}
// Regel 1: leer oder Hilfebefehl.
if (!text) return fertig('leere Nachricht');
if (/^\/(start|hilfe|help)\b/i.test(text)) return fertig('Hilfe angefordert');
// Zu lange Texte kuerzen wie K1 mit max_quelltext.
if (text.length > max) { text = text.slice(0, max); hinweise.push('Text auf ' + max + ' Zeichen gekürzt'); }
// Regel 2: Kundenkuerzel als erstes Wort, sonst Standardkunde.
const erstes = text.split(' ')[0].toLowerCase().replace(/[:,;.]+$/, '');
if (kuerzel.includes(erstes)) {
  aus.customer_code = erstes;
  aus.customer_recognized = true;
  const leer = text.indexOf(' ');
  text = leer > 0 ? text.slice(leer + 1).trim() : '';
} else {
  aus.customer_code = standard;
}
if (!aus.customer_code) return fertig('kein Standardkunde eingestellt');
if (!listeFehlt && !kuerzel.includes(aus.customer_code)) return fertig('Kunde ' + aus.customer_code + ' ist in k1_kunden nicht aktiv');
if (!text) return fertig('nur ein Kundenkürzel, kein Auftrag');
// Regel 3: Research-Befehl.
const research = text.match(/^(\/research|recherchier(e|en)?)\b\s*:?\s*(.*)$/i);
const url = (text.match(/https?:\/\/\S+/i) || [''])[0];
const ohneUrl = url ? text.replace(url, '').trim() : text;
if (research) {
  aus.source_type = 'Research';
  aus.topic = research[3].trim();
} else if (url && /(youtube\.com\/(watch|shorts)|youtu\.be\/)/i.test(url)) {
  // Regel 4: YouTube-Link.
  aus.source_type = 'YouTube-Link';
  aus.source = url;
  aus.topic = ohneUrl || 'Beitrag zum verlinkten Video';
} else if (url) {
  // Regel 5: andere Adresse ist ein Artikel-Link.
  aus.source_type = 'Artikel-Link';
  aus.source = url;
  aus.topic = ohneUrl || 'Beitrag zum verlinkten Artikel';
} else if (text.length > 300) {
  // Regel 6: langer Text ist eigener Text, weil K1 als Thema hoechstens 300 Zeichen annimmt.
  aus.source_type = 'Eigener Text';
  aus.source = text;
  aus.topic = (text.split(/(?<=[.!?])\s/)[0] || text).slice(0, 120);
} else {
  // Regel 7: sonst Thema.
  aus.source_type = 'Thema';
  aus.topic = text;
}
aus.topic = aus.topic.slice(0, 300);
// Pruefung wie vorgesehen: Thema mindestens 3 Zeichen.
if (aus.topic.length < 3) return fertig('Thema zu kurz');
return fertig('');
